""" Get the string to add to the input file.

    :param nset: Name of node set from which output should be output
    :type nset: str

    :param varstr: comma separated list of variables to output
    :type varstr: str

    :param frequency: How often to write output (increments)
    :type frequency: int

    :returns: The string to add
    :rtype: str

    """
def get_node_file_output_str(
    nset: Any, varstr: Any, frequency: Any = 99999999
) -> object {
    output_str = (
        ('*NODE FILE, NSET=' + nset + ', FREQUENCY=%0.0f \n' + varstr) % frequency
    );
    return output_str;
}

test_blocks:
test "t0" {
    assert (
        get_node_file_output_str('nset', 'N', 0)
        == '*NODE FILE, NSET=nset, FREQUENCY=0 \nN'
    );;
}

test "t1" {
    assert (
        get_node_file_output_str('1', '2')
        == '*NODE FILE, NSET=1, FREQUENCY=99999999 \n2'
    );;
}

test "t2" {
    assert (
        get_node_file_output_str('foo', 'N, M, O, T')
        == ('*NODE FILE, NSET=foo, FREQUENCY=%0.0f \nN, M, O, T' % 99999999)
    );;
}

test "t3" {
    assert (
        get_node_file_output_str('nset', 'N')
        == '*NODE FILE, NSET=nset, FREQUENCY=99999999 \nN'
    );;
}

test "t4" {
    assert (
        get_node_file_output_str('nset', 'N', 99999999)
        == '*NODE FILE, NSET=nset, FREQUENCY=99999999 \nN'
    );;
}

test "t5" {
    assert (
        get_node_file_output_str('ALL', 'U')
        == '*NODE FILE, NSET=ALL, FREQUENCY=99999999 \nU'
    );;
}

test "t6" {
    assert (
        get_node_file_output_str('1', '2', 3) == '*NODE FILE, NSET=1, FREQUENCY=3 \n2'
    );;
}
